Tr.Begin();
int[] votes = { 2, 1, 3, 2, 2, 1 };
Tr.S("الأصوات: رقم المرشح في كل خانة.", "votes", votes);
int[] count = new int[4];
Tr.S("مصفوفة عدّادات، كلها صفر.", "count", count);
for (int i = 0; i < votes.Length; i++)
{ //~
    count[votes[i]]++;
    Tr.S("الصوت " + votes[i] + " يزيد الخانة count[" + votes[i] + "].", "i", i, "count", count);
} //~
Tr.Drop("i");
Console.WriteLine(count[1] + " " + count[2] + " " + count[3]);
Tr.S("الطباعة: 2 3 1.");
Tr.End();

Tr.Begin();
int[] a = { 1, 2, 3, 4 };
Tr.S("المصفوفة قبل التدوير.", "a", a);
int first = a[0];
Tr.S("نحفظ العنصر الأول.", "first", first);
for (int i = 0; i < a.Length - 1; i++)
{ //~
    a[i] = a[i + 1];
    Tr.S("a[" + i + "] يأخذ قيمة a[" + (i + 1) + "].", "i", i, "a", a);
} //~
Tr.Drop("i");
a[a.Length - 1] = first;
Tr.S("نضع المحفوظ في آخر خانة.", "a", a);
for (int i = 0; i < a.Length; i++)
{ //~
    Console.Write(a[i] + " ");
    Tr.S("نطبع a[" + i + "].", "i", i);
} //~
Tr.Drop("i");
Tr.End();
